### Hibák listája
A kódban található összes konkrét hiba a következő:[1]

- Felesleges `import time` sor a 7. sorban, mivel a modul nincs sehol használva a kódban.[1]
- Több komment sor van jelen, pl. `# Cerebras client inicializálás` a 14. sorban, `# Chat történet tárolása...` a 19. sorban, `# Történet kezelése` a 45. sorban, stb., amelyek eltávolítása szükséges a production ready kódhoz.[1]
- A `chat()` függvény `except` részében `print(f"Hiba történt: {str(e)}")` hívás a 78. sorban, ami production környezetben nem megfelelő, eltávolítás vagy logging-ra cserélés javasolt.[1]
- A `clear_conversation()` függvényben a `return` mindig végrehajtódik a 135. sorban, így ha a `conversation_id` nem létezik a `conversations`-ben, mégis "success" üzenetet ad vissza anélkül, hogy bármit tenne; javítsuk úgy, hogy mindig beállítsa a listát üresre.[1]
- Nincs explicit kezelés a `request.json` parse hibáira mindegyik route-ban, ami 400-as hibát okozhat rossz JSON esetén; adjunk hozzá try-except blokkot a data kinyeréséhez.[1]
- A beszélgetés története (`conversations`) korlátlanul nőhet, ami token túllépést okozhat a modellnél; adjunk hozzá korlátozást, pl. maximum 20 üzenet megtartása.[1]
- A streaming `generate()` függvényben `full_response += content` használata nem optimális teljesítményű hosszú válaszoknál, mert string immutabilitás miatt; cseréljük listára és `''.join()`-ra a gyorsabb concatenációhoz.[1]
- A `app.run(debug=True)` a 142. sorban production-ben biztonsági kockázat, állítsuk `debug=False`-ra.[1]
- Nincs rate limiting vagy további validáció a bemeneten, de ez funkcionális hiba production-ben; hozzáadunk alap input hossz korlátozást a user_message-re.[1]

### Javított Kód
```python
import os
from flask import Flask, request, jsonify, Response
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras
import json

app = Flask(__name__)
CORS(app)

cerebras_api_key = os.environ.get("CEREBRAS_API_KEY")
if not cerebras_api_key:
    raise ValueError("CEREBRAS_API_KEY környezeti változó nincs beállítva!")
client = Cerebras(api_key=cerebras_api_key)

conversations = {}

@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({"status": "healthy", "model": "gpt-oss-120b"}), 200

@app.route('/api/chat', methods=['POST'])
def chat():
    try:
        data = request.get_json()
        if data is None:
            return jsonify({"error": "Érvénytelen JSON"}), 400
        user_message = data.get('message', '').strip()
        conversation_id = data.get('conversation_id', 'default')
        if not user_message or len(user_message) > 10000:
            return jsonify({"error": "Üres vagy túl hosszú üzenet"}), 400
        if conversation_id not in conversations:
            conversations[conversation_id] = []
        conversations[conversation_id].append({
            "role": "user",
            "content": user_message
        })
        response = client.chat.completions.create(
            model="gpt-oss-120b",
            messages=conversations[conversation_id],
            max_completion_tokens=65000,
            reasoning_effort="low",
            temperature=0.7,
            stream=False
        )
        ai_response = response.choices[0].message.content
        conversations[conversation_id].append({
            "role": "assistant",
            "content": ai_response
        })
        while len(conversations[conversation_id]) > 20:
            conversations[conversation_id].pop(0)
        return jsonify({
            "response": ai_response,
            "conversation_id": conversation_id,
            "model": "gpt-oss-120b",
            "tokens_used": response.usage.total_tokens if hasattr(response, 'usage') else None
        }), 200
    except Exception as e:
        return jsonify({"error": f"Szerver hiba: {str(e)}"}), 500

@app.route('/api/chat/stream', methods=['POST'])
def chat_stream():
    try:
        data = request.get_json()
        if data is None:
            return jsonify({"error": "Érvénytelen JSON"}), 400
        user_message = data.get('message', '').strip()
        conversation_id = data.get('conversation_id', 'default')
        if not user_message or len(user_message) > 10000:
            return jsonify({"error": "Üres vagy túl hosszú üzenet"}), 400
        if conversation_id not in conversations:
            conversations[conversation_id] = []
        conversations[conversation_id].append({
            "role": "user",
            "content": user_message
        })
        def generate():
            try:
                stream = client.chat.completions.create(
                    model="gpt-oss-120b",
                    messages=conversations[conversation_id],
                    max_completion_tokens=65000,
                    reasoning_effort="low",
                    temperature=0.7,
                    stream=True
                )
                full_parts = []
                for chunk in stream:
                    if chunk.choices[0].delta.content:
                        content = chunk.choices[0].delta.content
                        full_parts.append(content)
                        yield f"data: {json.dumps({'content': content})}\n\n"
                full_response = ''.join(full_parts)
                conversations[conversation_id].append({
                    "role": "assistant",
                    "content": full_response
                })
                while len(conversations[conversation_id]) > 20:
                    conversations[conversation_id].pop(0)
                yield f"data: {json.dumps({'done': True})}\n\n"
            except Exception as e:
                yield f"data: {json.dumps({'error': str(e)})}\n\n"
        return Response(generate(), mimetype='text/event-stream')
    except Exception as e:
        return jsonify({"error": f"Szerver hiba: {str(e)}"}), 500

@app.route('/api/conversation/clear', methods=['POST'])
def clear_conversation():
    try:
        data = request.get_json()
        if data is None:
            return jsonify({"error": "Érvénytelen JSON"}), 400
        conversation_id = data.get('conversation_id', 'default')
        conversations[conversation_id] = []
        return jsonify({"success": True, "message": "Beszélgetés törölve"}), 200
    except Exception as e:
        return jsonify({"error": f"Szerver hiba: {str(e)}"}), 500

@app.route('/api/conversation/history', methods=['GET'])
def get_history():
    conversation_id = request.args.get('conversation_id', 'default')
    history = conversations.get(conversation_id, [])
    return jsonify({"history": history}), 200

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 5000))
    app.run(host='0.0.0.0', port=port, debug=False)
```
